onClick:
{{
  (() => {
    const refCmd = Input_Ref_Commande_Fournisseur.text?.trim();

    if (!refCmd) {
      showAlert('Veuillez saisir une référence de commande !', 'warning');
      return;
    }

    Update_Statut_Commande_Masse.run()
      .then(() => storeValue('commande_selection', {}))
      .then(() => Get_Achats_Pool.run())
      .then(() => Get_Fournisseurs_Achats.run())
      .then(() => closeModal('modal_valider_commande_fournis')) // C'est ici que le nom est corrigé
      .then(() => showAlert(`Commande "${refCmd}" validée avec succès !`, 'success'))
      .catch((err) => showAlert('Erreur lors de la validation : ' + err.message, 'error'));
  })()
}}
